var orders = List.of(
    new Order(1L, "Laptop", 999.99),
    new Order(2L, "Mouse", 29.99),
    new Order(3L, "Keyboard", 79.99)
);

// 1. For-each loop - cleanest for read-only
for (Order order : orders) {
    System.out.println(order.item());
}

// 2. Iterator - allows safe removal
var mutableOrders = new ArrayList<>(orders);
var iterator = mutableOrders.iterator();
while (iterator.hasNext()) {
    var order = iterator.next();
    if (order.price() < 50.0) {
        iterator.remove(); // safe removal during iteration
    }
}

// 3. ListIterator - bidirectional traversal
var listIterator = mutableOrders.listIterator(mutableOrders.size());
while (listIterator.hasPrevious()) {
    var order = listIterator.previous(); // traverse backwards
    System.out.println(order.item());
}

// 4. forEach with lambda - functional style
orders.forEach(order -> System.out.println(order.item()));

record Order(Long id, String item, double price) {}

var orders = new ArrayList<>(List.of(
    new Order(1L, "Laptop", 999.99),
    new Order(2L, "Mouse", 29.99),
    new Order(3L, "Keyboard", 79.99),
    new Order(4L, "Cable", 9.99)
));

// WRONG: throws ConcurrentModificationException
// for (var order : orders) {
//     if (order.price() < 50.0) {
//         orders.remove(order); // modifies collection during iteration
//     }
// }

// FIX 1: Use iterator.remove() - most efficient
var iterator = orders.iterator();
while (iterator.hasNext()) {
    var order = iterator.next();
    if (order.price() < 50.0) {
        iterator.remove(); // safe removal through iterator
    }
}

// FIX 2: Collect to remove, then removeAll - cleaner for complex logic
var toRemove = new ArrayList<Order>();
for (var order : orders) {
    if (order.price() < 50.0) {
        toRemove.add(order);
    }
}
orders.removeAll(toRemove);

// FIX 3: removeIf with predicate - most concise
orders.removeIf(order -> order.price() < 50.0);

record Order(Long id, String item, double price) {}
